import os
import time

class CacheManager:
    def __init__(self):
        self.cache = {}
        self.hits = 0
        self.misses = 0

    def get(self, key):
        if key in self.cache and self.cache[key][1] > time.time():
            self.hits += 1
            return self.cache[key][0]
        else:
            self.misses += 1
            return None

    def set(self, key, value, ttl=3600):
        self.cache[key] = (value, time.time() + ttl)

    def delete(self, key):
        if key in self.cache:
            del self.cache[key]

    def cleanup(self):
        current_time = time.time()
        keys_to_delete = [key for key, (_, expiry) in self.cache.items() if expiry < current_time]
        for key in keys_to_delete:
            del self.cache[key]

    def stats(self):
        items = len(self.cache)
        hit_rate = (self.hits / (self.hits + self.misses)) if (self.hits + self.misses) > 0 else 0
        return {
            'items': items,
            'hits': self.hits,
            'misses': self.misses,
            'hit_rate': hit_rate
        }

