from collections import OrderedDict
import threading

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            if key not in self.cache:
                return -1
            else:
                value = self.cache[key]
                self.cache.move_to_end(key)
                return value

    def put(self, key, value):
        with self.lock:
            if key in self.cache:
                del self.cache[key]
            elif len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
            self.cache[key] = value

from typing import Tuple, List
import os

def splitter(file_path: str, chunk_size: int = 1024) -> Tuple[List[str], None]:
    """
    Разделяет файл на части и возвращает список путей к этим частям.

    Args:
        file_path (str): Путь к файлу, который нужно разделить.
        chunk_size (int): Размер каждой части в байтах. По умолчанию 1024.

    Returns:
        Tuple[List[str], None]: Кортеж, содержащий список путей к частям файла и None.
    """
    try:
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File {file_path} does not exist")

        with open(file_path, 'rb') as file:
            parts = []
            part_number = 0
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                part_path = f"{file_path}.part{part_number}"
                with open(part_path, 'wb') as part_file:
                    part_file.write(chunk)
                parts.append(part_path)
                part_number += 1

        return parts, None
    except (KeyError, IndexError) as e:
        print(f"An error occurred: {e}")
        return None, str(e)
    except FileNotFoundError as e:
        print(f"File not found: {e}")
        return None, str(e)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None, str(e)

