from typing import Any, Dict

class DatabaseMock:
    def __init__(self):
        self.data: Dict[str, Any] = {}

    def execute(self, query: str, params: Dict[str, Any]) -> Any:
        if query.startswith("SELECT"):
            return self._select(params)
        elif query.startswith("INSERT"):
            return self._insert(params)
        else:
            raise ValueError(f"Unknown query type: {query}")

    def _select(self, params: Dict[str, Any]) -> Any:
        key = params.get("key")
        if key is None:
            raise KeyError("Key is required for SELECT query")
        return self.data.get(key, None)

    def _insert(self, params: Dict[str, Any]) -> Any:
        key = params.get("key")
        value = params.get("value")
        if key is None or value is None:
            raise ValueError("Both key and value are required for INSERT query")
        self.data[key] = value
        return True

import time

def validator(max_retries=3, delay=1):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except (IOError, OSError) as e:
                    print(f"Attempt {attempts + 1} failed due to IOError/OSError: {e}")
                    time.sleep(delay)
                    attempts += 1
                except Exception as e:
                    print(f"Attempt {attempts + 1} failed due to an unexpected error: {e}")
                    break
            raise Exception("All retry attempts failed")
        return wrapper
    return decorator

