class _TrieNode:
    """
    Internal node of the trie.
    * `children` – mapping from a character to the next node.
    * `is_word` – True if a word ends in this node.
    """
    __slots__ = ("children", "is_word")

    def __init__(self) -> None:
        self.children: Dict[str, _TrieNode] = {}
        self.is_word: bool = False


class Trie:
    """
    A classic prefix‑tree (Trie) with four public operations:

    * `insert(word)` – add a word.
    * `search(word)` – return True iff the exact word is stored.
    * `starts_with(prefix)` – return True iff any stored word begins with *prefix*.
    * `autocomplete(prefix)` – return a list of all stored words that start with *prefix*.

    All operations are implemented recursively (via private helper methods).
    """

    def __init__(self) -> None:
        self._root = _TrieNode()

    # --------------------------------------------------------------------- #
    #  PUBLIC API
    # --------------------------------------------------------------------- #
    def insert(self, word: str) -> None:
        """Insert *word* into the trie."""
        if not isinstance(word, str):
            raise TypeError("word must be a string")
        self._insert_recursive(self._root, word, 0)

    def search(self, word: str) -> bool:
        """Return True iff *word* is present in the trie."""
        if not isinstance(word, str):
            raise TypeError("word must be a string")
        return self._search_recursive(self._root, word, 0)

    def starts_with(self, prefix: str) -> bool:
        """Return True iff there exists at least one word that starts with *prefix*."""
        if not isinstance(prefix, str):
            raise TypeError("prefix must be a string")
        return self._starts_with_recursive(self._root, prefix, 0)

    def autocomplete(self, prefix: str) -> List[str]:
        """
        Return a list of all words stored in the trie that start with *prefix*.
        The list is sorted lexicographically.
        """
        if not isinstance(prefix, str):
            raise TypeError("prefix must be a string")
        node = self._traverse_to_node(self._root, prefix, 0)
        if node is None:
            return []                     # no such prefix → empty result
        results: List[str] = []
        self._collect_words(node, prefix, results)
        results.sort()
        return results

    # --------------------------------------------------------------------- #
    #  PRIVATE RECURSIVE HELPERS
    # --------------------------------------------------------------------- #
    def _insert_recursive(self, node: _TrieNode, word: str, idx: int) -> None:
        """Recursively insert characters of *word* starting at position *idx*."""
        if idx == len(word):               # reached the end → mark word
            node.is_word = True
            return

        ch = word[idx]
        if ch not in node.children:
            node.children[ch] = _TrieNode()
        # recurse on the child that corresponds to the current character
        self._insert_recursive(node.children[ch], word, idx + 1)

    def _search_recursive(self, node: _TrieNode, word: str, idx: int) -> bool:
        """Recursively check whether *word* exists."""
        if idx == len(word):
            return node.is_word

        ch = word[idx]
        child = node.children.get(ch)
        if child is None:
            return False
        return self._search_recursive(child, word, idx + 1)

    def _starts_with_recursive(self, node: _TrieNode, prefix: str, idx: int) -> bool:
        """Recursively verify that *prefix* exists as a path in the trie."""
        if idx == len(prefix):
            return True                     # all characters of the prefix were found

        ch = prefix[idx]
        child = node.children.get(ch)
        if child is None:
            return False
        return self._starts_with_recursive(child, prefix, idx + 1)

    def _traverse_to_node(
        self, node: _TrieNode, key: str, idx: int
    ) -> Optional[_TrieNode]:
        """
        Walk down the trie following *key* (word or prefix) and return the node
        that corresponds to the last character, or None if the path does not exist.
        """
        if idx == len(key):
            return node
        ch = key[idx]
        child = node.children.get(ch)
        if child is None:
            return None
        return self._traverse_to_node(child, key, idx + 1)

    def _collect_words(
        self, node: _TrieNode, current_prefix: str, out: List[str]
    ) -> None:
        """
        Depth‑first collection of all words that start from *node*.
        `current_prefix` already contains the characters that lead to *node*.
        """
