class Token:
    """Токен в выражении"""
    __slots__ = ('type', 'value')

    def __init__(self, type: str, value: Union[int, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'


class Parser:
    """Парсер выражений"""
    __slots__ = ('tokens', 'pos')

    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> Union[int, float]:
        """Разобрать выражение"""
        result = self.parse_expr()
        if self.pos < len(self.tokens):
            raise ValueError("Неправильное выражение")
        return result

    def parse_expr(self) -> Union[int, float]:
        """Разобрать выражение"""
        result = self.parse_term()
        while self.pos < len(self.tokens) and self.tokens[self.pos].type in ('+', '-'):
            if self.tokens[self.pos].type == '+':
                self.pos += 1
                result += self.parse_term()
            else:
                self.pos += 1
                result -= self.parse_term()
        return result

    def parse_term(self) -> Union[int, float]:
        """Разобрать член выражения"""
        result = self.parse_factor()
        while self.pos < len(self.tokens) and self.tokens[self.pos].type in ('*', '/'):
            if self.tokens[self.pos].type == '*':
                self.pos += 1
                result *= self.parse_factor()
            else:
                self.pos += 1
                result /= self.parse_factor()
        return result

    def parse_factor(self) -> Union[int, float]:
        """Разобрать фактор выражения"""
        if self.pos >= len(self.tokens):
            raise ValueError("Неправильное выражение")
        token = self.tokens[self.pos]
        self.pos += 1
        if token.type == 'number':
            return token.value
        else:
            raise ValueError("Неправильное выражение")


def tokenize(expression: str) -> list[Token]:
    """Токенизировать выражение"""
    tokens = []
    current_token = ''
    for char in expression:
        if char.isdigit() or char == '.':
            current_token += char
        elif char in ('+', '-', '*', '/'):
            if current_token:
                tokens.append(Token('number', float(current_token)))
                current_token = ''
            tokens.append(Token(char, char))
        else:
            if current_token:
                tokens.append(Token('number', float(current_token)))
                current_token = ''
    if current_token:
        tokens.append(Token('number', float(current_token)))
    return tokens


