class StateMachineError(RuntimeError):
    """Базовый класс ошибок машины состояний."""


class UnknownStateError(StateMachineError):
    """Состояние, к которому обращаются, не объявлено."""


class UnknownEventError(StateMachineError):
    """Для текущего состояния нет перехода по данному событию."""


class StateMachine:
    """
    Простейшая конечная автоматная машина, построенная полностью на словарях.

    Методы
    -------
    add_state(name)
        Добавляет новое состояние.
    add_transition(from, to, event)
        Добавляет переход между состояниями по событию.
    trigger(event)
        Вызывает переход в следующее состояние по событию.
    get_state()
        Возвращает текущее состояние машины.
    """

    def __init__(self):
        self.states = {}
        self.transitions = {}
        self.current_state = None

    def add_state(self, name):
        if name not in self.states:
            self.states[name] = []
            print(f"State '{name}' added.")
        else:
            print(f"State '{name}' already exists.")

    def add_transition(self, from_state, to_state, event):
        if from_state in self.states and to_state in self.states:
            if (from_state, event) not in self.transitions:
                self.transitions[(from_state, event)] = to_state
                print(f"Transition from '{from_state}' to '{to_state}' on event '{event}' added.")
            else:
                print(f"Transition from '{from_state}' on event '{event}' already exists.")
        else:
            raise UnknownStateError("One or both states do not exist.")

    def trigger(self, event):
        if self.current_state is None:
            raise RuntimeError("Current state is not set. Please set an initial state.")

        transition_key = (self.current_state, event)
        if transition_key in self.transitions:
            self.current_state = self.transitions[transition_key]
            print(f"Transitioned to state '{self.current_state}' on event '{event}'.")
        else:
            raise UnknownEventError(f"No transition defined for current state '{self.current_state}' and event '{event}'.")

    def get_state(self):
        return self.current_state

import weakref

class EventBus:
    def __init__(self):
        self._subscriptions = {}

    def subscribe(self, event, handler):
        """
        Подписаться на событие.

        :param event: Имя события
        :param handler: Функция-обработчик события
        """
        if event not in self._subscriptions:
            self._subscriptions[event] = []
        self._subscriptions[event].append(weakref.ref(handler))

    def unsubscribe(self, event, handler):
        """
        Отписаться от события.

        :param event: Имя события
        :param handler: Функция-обработчик события
        """
        if event in self._subscriptions:
            self._subscriptions[event] = [ref for ref in self._subscriptions[event] if ref() != handler]

    def emit(self, event, data):
        """
        Вызвать событие.

        :param event: Имя события
        :param data: Данные, передаваемые обработчикам события
        """
        if event in self._subscriptions:
            for ref in self._subscriptions[event]:
                handler = ref()
                if handler:
                    handler(data)

