class SignalSlot:
    def __init__(self):
        self.slots = defaultdict(list)

    def connect(self, signal, slot):
        """Подключает слот к сигналу."""
        try:
            if callable(slot):
                self.slots[signal].append(slot)
            else:
                raise ValueError("Слот должен быть вызываемым объектом.")
        except Exception as e:
            print(f"Ошибка при подключении слота: {e}")

    def emit(self, signal, *args):
        """Генерирует сигнал и вызывает соответствующие слоты."""
        try:
            for slot in self.slots[signal]:
                slot(*args)
        except Exception as e:
            print(f"Ошибка при генерации сигнала: {e}")

    def disconnect(self, signal, slot):
        """Отключает слот от сигнала."""
        try:
            if slot in self.slots[signal]:
                self.slots[signal].remove(slot)
            else:
                raise ValueError("Слот не подключен к данному сигналу.")
        except Exception as e:
            print(f"Ошибка при отключении слота: {e}")

