from abc import ABC, abstractmethod

class Command(ABC):
    @abstractmethod
    def execute(self) -> None:
        pass

    @abstractmethod
    def undo(self) -> None:
        pass

class Invoker:
    def __init__(self):
        self._commands: list[Command] = []

    def execute_command(self, cmd: Command) -> None:
        try:
            cmd.execute()
            self._commands.append(cmd)
        except Exception as e:
            print(f"Error executing command: {e}")

    def undo_command(self) -> None:
        if self._commands:
            try:
                last_cmd = self._commands.pop()
                last_cmd.undo()
            except Exception as e:
                print(f"Error undoing command: {e}")

