from threading import Lock
from typing import Any, Optional

class Node:
    """Узел списка."""
    def __init__(self, value: Any):
        self.value = value
        self.next: Optional[Node] = None

class LinkedList:
    """Thread-safe LinkedList."""
    def __init__(self):
        self.head: Optional[Node] = None
        self.tail: Optional[Node] = None
        self.lock = Lock()

    def append(self, value: Any) -> None:
        """Добавить элемент в конец списка."""
        with self.lock:
            node = Node(value)
            if not self.head:
                self.head = node
                self.tail = node
            else:
                self.tail.next = node
                self.tail = node

    def remove(self, value: Any) -> bool:
        """Удалить первый элемент со значением value."""
        with self.lock:
            if not self.head:
                return False
            if self.head.value == value:
                self.head = self.head.next
                if not self.head:
                    self.tail = None
                return True
            current = self.head
            while current.next:
                if current.next.value == value:
                    current.next = current.next.next
                    if not current.next:
                        self.tail = current
                    return True
                current = current.next
            return False

    def __iter__(self) -> iter:
        """Итератор по списку."""
        with self.lock:
            current = self.head
            while current:
                yield current.value
                current = current.next

    def __len__(self) -> int:
        """Количество элементов в списке."""
        with self.lock:
            count = 0
            current = self.head
            while current:
                count += 1
                current = current.next
            return count

    def __repr__(self) -> str:
        """Строковое представление списка."""
        with self.lock:
            values = []
            current = self.head
            while current:
                values.append(str(current.value))
                current = current.next
            return ' -> '.join(values)

