class Cache(Generic[K, V]):
    """
    Thread-safe LRU-кэш с ограничением по размеру.
    Ключи должны быть хешируемыми (hashable).
    """
    def __init__(self, capacity: int = 100) -> None:
        if capacity <= 0:
            raise ValueError("Вместимость кэша должна быть положительным целым числом.")

        self._capacity = capacity
        self._cache = OrderedDict()

    def add(self, key: K, value: V) -> None:
        try:
            if key in self._cache:
                del self._cache[key]
            elif len(self._cache) >= self._capacity:
                self._cache.popitem(last=False)
            self._cache[key] = value
        except Exception as e:
            print(f"Ошибка при добавлении элемента: {e}")

    def remove(self, key: K) -> None:
        try:
            if key in self._cache:
                del self._cache[key]
            else:
                raise KeyError("Ключ не найден в кэше.")
        except Exception as e:
            print(f"Ошибка при удалении элемента: {e}")

    def find(self, key: K) -> Optional[V]:
        try:
            if key in self._cache:
                value = self._cache[key]
                self._cache.move_to_end(key)
                return value
            else:
                raise KeyError("Ключ не найден в кэше.")
        except Exception as e:
            print(f"Ошибка при поиске элемента: {e}")
            return None

