import logging
import time
from typing import Callable, Any
from functools import wraps

logging.basicConfig(level=logging.INFO)

def dispatcher(max_attempts: int = 3, delay: float = 1) -> Callable:
    """
    Декоратор для retry логики.

    :param max_attempts: Максимальное количество попыток
    :param delay: Задержка между попытками
    :return: Декоратор
    """
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    logging.error(f"Attempt {attempts + 1} failed: {e}")
                    attempts += 1
                    if attempts < max_attempts:
                        logging.info(f"Retrying in {delay} seconds...")
                        time.sleep(delay)
                    else:
                        logging.error(f"Max attempts reached. Giving up.")
                        raise
        return wrapper
    return decorator

