# Определяем универсальный тип T для поддержки любой типизации (int, str, CustomClass и т.д.)
T = TypeVar('T')

class AsyncIterator(Generic[T]):
    """
    Асинхронный контейнер, поддерживающий добавление, удаление и поиск элементов.
    Реализует протокол асинхронного итератора.
    """

    def __init__(self):
        self._items: List[T] = []
        self._index: int = 0

    async def add(self, item: T) -> None:
        try:
            if not isinstance(item, T):
                raise TypeError(f"Expected type {T}, got {type(item)}")
            self._items.append(item)
        except Exception as e:
            print(f"Error adding item: {e}")

    async def remove(self, item: T) -> bool:
        try:
            if not isinstance(item, T):
                raise TypeError(f"Expected type {T}, got {type(item)}")
            if item in self._items:
                self._items.remove(item)
                return True
            else:
                return False
        except Exception as e:
            print(f"Error removing item: {e}")
            return False

    async def find(self, query: T) -> Optional[List[T]]:
        try:
            if not isinstance(query, T):
                raise TypeError(f"Expected type {T}, got {type(query)}")
            return [item for item in self._items if item == query]
        except Exception as e:
            print(f"Error finding items: {e}")
            return None

    async def __aiter__(self) -> 'AsyncIterator':
        self._index = 0
        return self

    async def __anext__(self) -> T:
        try:
            if self._index < len(self._items):
                result = self._items[self._index]
                self._index += 1
                return result
            else:
                raise StopAsyncIteration
        except Exception as e:
            print(f"Error during iteration: {e}")
            raise StopAsyncIteration from e

