import socket
from typing import Optional

class Parser:
    def __init__(self, host: str, port: int):
        """
        Инициализация парсера.

        :param host: Хост для подключения
        :param port: Порт для подключения
        """
        self.host = host
        self.port = port
        self.socket: Optional[socket.socket] = None

    def connect(self) -> None:
        """
        Подключение к хосту.

        :raises ConnectionError: Если подключение не удалось
        """
        if self.socket is not None:
            raise RuntimeError("Сокет уже открыт")
        try:
            self.socket = socket.create_connection((self.host, self.port))
        except (socket.error, OSError) as e:
            raise ConnectionError(f"Не удалось подключиться: {e}")

    def send(self, data: bytes) -> int:
        """
        Отправка данных.

        :param data: Данные для отправки
        :return: Количество отправленных байт
        :raises RuntimeError: Если сокет не открыт
        :raises socket.error: Если произошла ошибка при отправке
        """
        if self.socket is None:
            raise RuntimeError("Сокет не открыт")
        try:
            return self.socket.send(data)
        except (socket.error, OSError) as e:
            raise socket.error(f"Ошибка при отправке данных: {e}")

    def close(self) -> None:
        """
        Закрытие соединения.

        :raises RuntimeError: Если сокет не открыт
        """
        if self.socket is None:
            raise RuntimeError("Сокет уже закрыт")
        try:
            self.socket.close()
        except (socket.error, OSError) as e:
            raise RuntimeError(f"Ошибка при закрытии соединения: {e}")
        finally:
            self.socket = None

