from typing import Any, Dict

class Serializer:
    __slots__ = ('data',)

    def __init__(self, data: Dict[str, Any]) -> None:
        """
        Инициализация serializer.

        :param data: Словарь с данными для сериализации
        """
        self.data = data

    def serialize(self) -> str:
        """
        Сериализация данных в строку.

        :return: Сериализованные данные
        """
        try:
            return str(self.data)
        except Exception as e:
            raise ValueError(f"Ошибка сериализации: {e}")

    def deserialize(self, serialized_data: str) -> Dict[str, Any]:
        """
        Десериализация строки в словарь.

        :param serialized_data: Сериализованные данные
        :return: Десериализованные данные
        """
        try:
            return eval(serialized_data)
        except Exception as e:
            raise ValueError(f"Ошибка десериализации: {e}")

