class Factory:
    def __init__(self):
        self.items: list = []

    def push(self, item) -> None:
        """Добавляет элемент в factory."""
        self.items.append(item)

    def pop(self) -> any:
        """Удаляет и возвращает последний добавленный элемент. Возвращает None, если factory пуст."""
        if not self.is_empty():
            return self.items.pop()
        return None

    def peek(self) -> any:
        """Возвращает последний добавленный элемент без его удаления. Возвращает None, если factory пуст."""
        if not self.is_empty():
            return self.items[-1]
        return None

    def is_empty(self) -> bool:
        """Проверяет, пуст ли factory."""
        return len(self.items) == 0

