        for scenario in scenarios:
            query = scenario.get("query", "")
            description = scenario.get("description", "Неизвестный сценарий")

            # Проверяем, есть ли соответствующий набор данных для каждого сценария
            if not any(dataset["query"] == query for dataset in datasets):
                print(f"Набор данных отсутствует для сценария: {description}")
                return False

        print("Все сценарии и граничные случаи охвачены наборами данных.")
        return True
    except Exception as e:
        print(f"Ошибка при валидации наборов данных: {e}")
        return False

