from abc import ABC, abstractmethod
from typing import List, Optional, TypeVar, Generic

T = TypeVar('T')


class Command(ABC):
    """Абстрактный класс команды"""

    @abstractmethod
    def execute(self) -> None:
        """Выполнить команду"""
        pass

    @abstractmethod
    def undo(self) -> None:
        """Отменить команду"""
        pass


class AddCommand(Command, Generic[T]):
    """Команда добавления элемента"""

    def __init__(self, receiver: 'Receiver[T]', item: T) -> None:
        self._receiver = receiver
        self._item = item

    def execute(self) -> None:
        self._receiver.add(self._item)

    def undo(self) -> None:
        self._receiver.remove(self._item)


class RemoveCommand(Command, Generic[T]):
    """Команда удаления элемента"""

    def __init__(self, receiver: 'Receiver[T]', item: T) -> None:
        self._receiver = receiver
        self._item = item

    def execute(self) -> None:
        self._receiver.remove(self._item)

    def undo(self) -> None:
        self._receiver.add(self._item)


class FindCommand(Command, Generic[T]):
    """Команда поиска элемента"""

    def __init__(self, receiver: 'Receiver[T]', item: T) -> None:
        self._receiver = receiver
        self._item = item
        self._result: Optional[T] = None

    def execute(self) -> None:
        self._result = self._receiver.find(self._item)

    def undo(self) -> None:
        # Поиск - операция только чтения, отмена не требуется
        pass

    def get_result(self) -> Optional[T]:
        """Получить результат поиска"""
        return self._result


class Receiver(Generic[T]):
    """Получатель команды - управляет коллекцией элементов"""

    def __init__(self) -> None:
        self._items: List[T] = []

    def add(self, item: T) -> bool:
        """
        Добавить элемент в коллекцию

        Args:
            item: Элемент для добавления

        Returns:
            bool: True если элемент добавлен, False если уже существует
        """
        if item is None:
            raise ValueError("Нельзя добавить None элемент")

        if item not in self._items:
            self._items.append(item)
            return True
        return False

    def remove(self, item: T) -> bool:
        """
        Удалить элемент из коллекции

        Args:
            item: Элемент для удаления

        Returns:
            bool: True если элемент удален, False если не найден
        """
        try:
            self._items.remove(item)
            return True
        except ValueError:
            return False

    def find(self, item: T) -> Optional[T]:
        """
        Найти элемент в коллекции

        Args:
            item: Элемент для поиска

        Returns:
            Optional[T]: Найденный элемент или None
        """
        if item in self._items:
            return item
        return None

    def get_all_items(self) -> List[T]:
        """Получить копию списка всех элементов"""
        return self._items.copy()

    def get_size(self) -> int:
        """Получить размер коллекции"""
        return len(self._items)


class Invoker:
    """Инвокер - выполняет команды и управляет историей"""

    def __init__(self) -> None:
        self._commands: List[Command] = []
        self._undo_stack: List[Command] = []

    def execute_command(self, command: Command) -> None:
        """
        Выполнить команду

        Args:
            command: Команда для выполнения
        """
        if command is None:
            raise ValueError("Команда не может быть None")

        command.execute()
        self._commands.append(command)
        # Очищаем стек отмены при новой команде
        self._undo_stack.clear()

    def undo(self) -> bool:
        """
        Отменить последнюю выполненную команду

        Returns:
            bool: True если отмена успешна, False если нет команд для отмены
        """
        if not self._commands:
            return False

        command = self._commands.pop()
        command.undo()
        self._undo_stack.append(command)
        return True

    def redo(self) -> bool:
        """
        Повторить отмененную команду

        Returns:
            bool: True если повтор успешен, False если нет команд для повтора
        """
        if not self._undo_stack:
            return False

        command = self._undo_stack.pop()
        command.execute()
        self._commands.append(command)
        return True

