from __future__ import annotations

from functools import lru_cache
from typing import Literal

# ----------------------------------------------------------------------
# Allowed temperature units
# ----------------------------------------------------------------------
TemperatureUnit = Literal["C", "F", "K"]   # Celsius, Fahrenheit, Kelvin


# ----------------------------------------------------------------------
# Memoized low‑level conversion helpers
# ----------------------------------------------------------------------
@lru_cache(maxsize=None)
def _c_to_f(celsius: float) -> float:
    """Celsius → Fahrenheit."""
    return celsius * 9.0 / 5.0 + 32.0


@lru_cache(maxsize=None)
def _f_to_c(fahrenheit: float) -> float:
    """Fahrenheit → Celsius."""
    return (fahrenheit - 32.0) * 5.0 / 9.0


@lru_cache(maxsize=None)
def _c_to_k(celsius: float) -> float:
    """Celsius → Kelvin."""
    return celsius + 273.15


@lru_cache(maxsize=None)
def _k_to_c(kelvin: float) -> float:
    """Kelvin → Celsius."""
    return kelvin - 273.15


@lru_cache(maxsize=None)
def _f_to_k(fahrenheit: float) -> float:
    """Fahrenheit → Kelvin (via Celsius)."""
    return _c_to_k(_f_to_c(fahrenheit))


@lru_cache(maxsize=None)
def _k_to_f(kelvin: float) -> float:
    """Kelvin → Fahrenheit (via Celsius)."""
    return _c_to_f(_k_to_c(kelvin))


# ----------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------
def convert_temperature(
    value: float,
    from_unit: TemperatureUnit,
    to_unit: TemperatureUnit,
) -> float:
    """
    Convert a temperature from one unit to another.

    Parameters
    ----------
    value: float
        Temperature value to convert. Must be a finite real number.
    from_unit: {"C", "F", "K"}
        Unit of ``value``.
    to_unit: {"C", "F", "K"}
        Desired output unit.

    Returns
    -------
    float
        Converted temperature.

    Raises
    ------
    TypeError
        If ``value`` is not a real number.
    ValueError
        If ``from_unit``/``to_unit`` is unsupported or if ``value`` is infinite/NaN.
    """
    # ----------------------- edge‑case validation -----------------------
    if not isinstance(value, (int, float)):
        raise TypeError(f"Temperature value must be a number, got {type(value)!r}")

    if isinstance(value, (float, int)) and (
        value != value or value in (float("inf"), -float("inf"))
    ):
        raise ValueError("Temperature value must be a finite number")

    if from_unit not in {"C", "F", "K"} or to_unit not in {"C", "F", "K"}:
        raise ValueError("Unsupported temperature unit. Use 'C', 'F' or 'K'.")

    if from_unit == to_unit:
        # Nothing to convert – return a plain float for consistency.
        return float(value)

    # -------------------------- actual conversion -----------------------
    if from_unit == "C" and to_unit == "F":
        return _c_to_f(value)
    if from_unit == "F" and to_unit == "C":
        return _f_to_c(value)
    if from_unit == "C" and to_unit == "K":
        return _c_to_k(value)
    if from_unit == "K" and to_unit == "C":
        return _k_to_c(value)
    if from_unit == "F" and to_unit == "K":
        return _f_to_k(value)
    if from_unit == "K" and to_unit == "F":
        return _k_to_f(value)

    # The code should never reach this point because of the checks above.
    raise RuntimeError("Unreachable conversion path")


