from __future__ import annotations

from functools import lru_cache
from typing import Literal, Tuple

# ----------------------------------------------------------------------
# Allowed temperature units
# ----------------------------------------------------------------------
TemperatureUnit = Literal["C", "F", "K"]   # Celsius, Fahrenheit, Kelvin


# ----------------------------------------------------------------------
# Memoized low-level conversion helpers
# ----------------------------------------------------------------------

@lru_cache(maxsize=None)
def _celsius_to_fahrenheit(celsius: float) -> float:
    return (celsius * 9/5) + 32

@lru_cache(maxsize=None)
def _fahrenheit_to_celsius(fahrenheit: float) -> float:
    return (fahrenheit - 32) * 5/9

@lru_cache(maxsize=None)
def _celsius_to_kelvin(celsius: float) -> float:
    return celsius + 273.15

@lru_cache(maxsize=None)
def _kelvin_to_celsius(kelvin: float) -> float:
    return kelvin - 273.15

@lru_cache(maxsize=None)
def _fahrenheit_to_kelvin(fahrenheit: float) -> float:
    return (_fahrenheit_to_celsius(fahrenheit) + 273.15)

@lru_cache(maxsize=None)
def _kelvin_to_fahrenheit(kelvin: float) -> float:
    return (_kelvin_to_celsius(kelvin) * 9/5) + 32


# ----------------------------------------------------------------------
# High-level conversion function with memoization
# ----------------------------------------------------------------------

def converter(value: float, from_unit: TemperatureUnit, to_unit: TemperatureUnit) -> float:
    """Converts temperature between Celsius, Fahrenheit, and Kelvin."""
    try:
        if value is None or not isinstance(value, (int, float)):
            raise ValueError("Temperature value must be a number.")

        conversion_map = {
            ("C", "F"): _celsius_to_fahrenheit,
            ("F", "C"): _fahrenheit_to_celsius,
            ("C", "K"): _celsius_to_kelvin,
            ("K", "C"): _kelvin_to_celsius,
            ("F", "K"): _fahrenheit_to_kelvin,
            ("K", "F"): _kelvin_to_fahrenheit,
        }

        conversion_function = conversion_map.get((from_unit, to_unit))

        if not conversion_function:
            raise ValueError(f"Conversion from {from_unit} to {to_unit} is not supported.")

        return conversion_function(value)
    except Exception as e:
        print(f"Error converting temperature: {e}")
        return None

