class SearchEngine:
    def __init__(self, data):
        self.data = sorted(data)  # Предполагаем, что данные можно отсортировать

    def find(self, query):
        try:
            left, right = 0, len(self.data) - 1
            while left <= right:
                mid = (left + right) // 2
                if self.data[mid] == query:
                    return mid
                elif self.data[mid] < query:
                    left = mid + 1
                else:
                    right = mid - 1
            return -1  # Если элемент не найден
        except Exception as e:
            print(f"Ошибка в методе find(): {e}")
            return None

