        self._status: IteratorStatus = IteratorStatus.STOPPED

    def start(self) -> None:
        """Запуск итератора"""
        if self._status == IteratorStatus.RUNNING:
            raise RuntimeError("Итератор уже запущен")
        self._status = IteratorStatus.RUNNING

