        """Остановка итератора"""
        if self._status == IteratorStatus.STOPPED:
            raise RuntimeError("Итератор уже остановлен")
        self._status = IteratorStatus.STOPPED

    def status(self) -> IteratorStatus:
        """Получение статуса итератора"""
        return self._status

