import queue
from threading import Lock

class ThreadSafePriorityQueue:
    def __init__(self):
        self._pq = queue.PriorityQueue()
        self._lock = Lock()

    def put(self, item: any) -> None:
        """Добавляет элемент в очередь с приоритетом."""
        if item is None:
            raise ValueError("Item cannot be None")
        with self._lock:
            self._pq.put(item)

    def get(self) -> any:
        """Извлекает и возвращает элемент с наивысшим приоритетом из очереди."""
        with self._lock:
            if self._pq.empty():
                raise queue.Empty("Queue is empty")
            return self._pq.get()

