import subprocess

def resolver(input_list: List[str], command: List[str]) -> List[Tuple[str, str]]:
    results = []
    for item in input_list:
        try:
            result = subprocess.run(command + [item], capture_output=True, text=True, check=True).stdout.strip()
            results.append((item, result))
        except subprocess.CalledProcessError as e:
            print(f"Failed to process {item}: {e.stderr}")
    return results

from typing import Any, List

class dispatcher:
    def __init__(self):
        self._items: List[Any] = []

    def add(self, item: Any) -> None:
        """Добавляет элемент в диспетчер."""
        if item is None:
            raise ValueError("Item cannot be None")
        self._items.append(item)

    def remove(self, item: Any) -> bool:
        """Удаляет элемент из диспетчера. Возвращает True если элемент был найден и удален."""
        try:
            self._items.remove(item)
            return True
        except ValueError:
            return False

    def find(self, query: Any) -> List[Any]:
        """Находит все элементы, соответствующие запросу."""
        if query is None:
            raise ValueError("Query cannot be None")
        return [item for item in self._items if item == query]

