from enum import Enum
from typing import Optional

class DispatcherStatus(Enum):
    """Статус диспетчера"""
    STOPPED = 1
    RUNNING = 2

class Dispatcher:
    """Класс диспетчера"""
    def __init__(self) -> None:
        """Инициализация диспетчера"""
        self._status: DispatcherStatus = DispatcherStatus.STOPPED

    def start(self) -> None:
        """Запуск диспетчера"""
        if self._status == DispatcherStatus.RUNNING:
            raise RuntimeError("Диспетчер уже запущен")
        self._status = DispatcherStatus.RUNNING
        print("Диспетчер запущен")

    def stop(self) -> None:
        """Остановка диспетчера"""
        if self._status == DispatcherStatus.STOPPED:
            raise RuntimeError("Диспетчер уже остановлен")
        self._status = DispatcherStatus.STOPPED
        print("Диспетчер остановлен")

    def status(self) -> DispatcherStatus:
        """Получение статуса диспетчера"""
        return self._status

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class Buffer:
    def __init__(self):
        self.head = None

    def add(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def remove(self, value):
        current = self.head
        previous = None
        while current:
            if current.value == value:
                if previous:
                    previous.next = current.next
                else:
                    self.head = current.next
                return
            previous = current
            current = current.next

    def find(self, value):
        current = self.head
        while current:
            if current.value == value:
                return True
            current = current.next
        return False

