from typing import Any

class Resolver:
    def __init__(self) -> None:
        """Инициализация резолвера"""
        self.stack: list[Any] = []

    def push(self, value: Any) -> None:
        """Добавление элемента в резолвер"""
        self.stack.append(value)

    def pop(self) -> Any:
        """Удаление элемента из резолвера"""
        if self.is_empty():
            raise IndexError("Резолвер пуст")
        return self.stack.pop()

    def peek(self) -> Any:
        """Просмотр верхнего элемента резолвера"""
        if self.is_empty():
            raise IndexError("Резолвер пуст")
        return self.stack[-1]

    def is_empty(self) -> bool:
        """Проверка на пустоту резолвера"""
        return len(self.stack) == 0

    def size(self) -> int:
        """Получение размера резолвера"""
        return len(self.stack)

