resolver.push(2)
resolver.push(3)
print(resolver.size())  # 3
print(resolver.peek())  # 3
print(resolver.pop())  # 3
print(resolver.size())  # 2
print(resolver.pop())  # 2
print(resolver.pop())  # 1
print(resolver.is_empty())  # True
try:
    resolver.pop()
except IndexError as e:
    print(e)  # Резолвер пуст

