import time

def splitter(max_retries=3, exp_backoff_factor=2):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Attempt {attempts + 1} failed: {e}")
                    delay = exp_backoff_factor ** attempts
                    time.sleep(delay)
                    attempts += 1
            raise Exception("Max retries exceeded")
        return wrapper
    return decorator

