class BinarySearch:
    def __init__(self, sorted_list):
        self.sorted_list = sorted_list

    def search(self, target):
        try:
            left, right = 0, len(self.sorted_list) - 1

            while left <= right:
                mid = (left + right) // 2
                if self.sorted_list[mid] == target:
                    return mid
                elif self.sorted_list[mid] < target:
                    left = mid + 1
                else:
                    right = mid - 1

            return -1
        except Exception as e:
            print(f"Ошибка: {e}")
            return -1

