class Splitter:
    """Класс для разбиения строки на части"""
    __slots__ = ('text', 'delimiter')

    def __init__(self, text: str, delimiter: str):
        self.text = text
        self.delimiter = delimiter

    def _lazy_splitter(self) -> List[str]:
        try:
            return iter(lambda: next(iter(self.text.split(self.delimiter)), None), None)
        except Exception as e:
            print(f"Ошибка при ленивом разбиении: {e}")
            return []

