def generate_bst(values):
    root = None
    for value in values:
        root = insert_into_bst(root, value)
    return root

def insert_into_bst(node, value):
    if node is None:
        return TreeNode(value)
    if value < node.value:
        node.left = insert_into_bst(node.left, value)
    else:
        node.right = insert_into_bst(node.right, value)
    return node

def generate_complete_binary_tree(values):
    if not values:
        return None
    root = TreeNode(values[0])
    queue = [root]
    i = 1
    while queue and i < len(values):
        current = queue.pop(0)
        current.left = TreeNode(values[i])
        queue.append(current.left)
        i += 1
        if i < len(values):
            current.right = TreeNode(values[i])
            queue.append(current.right)
            i += 1
    return root

def generate_avl_tree(values):
    def balance_factor(node):
        if not node:
            return 0
        return height(node.left) - height(node.right)

    def height(node):
        if not node:
            return 0
        return max(height(node.left), height(node.right)) + 1

    def left_rotate(z):
        y = z.right
        T2 = y.left
        y.left = z
        z.right = T2
        return y

    def right_rotate(y):
        x = y.left
        T3 = x.right
        x.right = y
        y.left = T3
        return x

    def insert(node, value):
        if not node:
            return TreeNode(value)
        elif value < node.value:
            node.left = insert(node.left, value)
        else:
            node.right = insert(node.right, value)

        balance = balance_factor(node)

        if balance > 1 and value < node.left.value:
            return right_rotate(node)

        if balance < -1 and value > node.right.value:
            return left_rotate(node)

        if balance > 1 and value > node.left.value:
            node.left = left_rotate(node.left)
            return right_rotate(node)

        if balance < -1 and value < node.right.value:
            node.right = right_rotate(node.right)
            return left_rotate(node)

        return node

    root = None
    for value in values:
        root = insert(root, value)
    return root

