        self.value = value
        self.next = None

class Dispatcher:
    def __init__(self):
        self.head = None

    def add(self, key, value):
        new_node = Node(key, value)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def remove(self, key):
        current = self.head
        previous = None
        while current:
            if current.key == key:
                if previous:
                    previous.next = current.next
                else:
                    self.head = current.next
                return
            previous = current
            current = current.next
        raise KeyError(f"Ключ {key} не найден.")

    def find(self, key):
        current = self.head
        while current:
            if current.key == key:
                return current.value
            current = current.next
        return None

