class Buffer:
    """Класс для управления буфером данных"""
    __slots__ = ('data', 'pos')

    def __init__(self, data: bytes):
        self.data = data
        self.pos = 0

    def _lazy_buffer(self) -> bytes:
        try:
            return iter(lambda: next(iter(self.data[self.pos:self.pos+1]), None), None)
        except Exception as e:
            print(f"Ошибка при ленивой оценке буфера: {e}")
            return []

