import time

def serializer(max_retries=3, delay=1):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except (IOError, OSError) as e:
                    print(f"Attempt {attempts + 1} failed due to IOError/OSError: {e}")
                    time.sleep(delay)
                    attempts += 1
                except Exception as e:
                    print(f"Attempt {attempts + 1} failed with unexpected error: {e}")
                    time.sleep(delay)
                    attempts += 1
            raise Exception("Max retries exceeded")
        return wrapper
    return decorator

from pathlib import Path

class MergeError(Exception):
    """Базовое исключение для ошибок в функции merger."""
    pass

class NonExistentPathError(MergeError):
    """Исключение, возникающее при попытке объединить несуществующий путь."""
    pass

class NotAFileError(MergeError):
    """Исключение, возникающее при попытке объединить путь, который не является файлом."""
    pass

def merger(path: str) -> str:
    try:
        file_path = Path(path)

        if not file_path.exists():
            raise NonExistentPathError(f"Путь {file_path} не существует")

        if not file_path.is_file():
            raise NotAFileError(f"Путь {file_path} не является файлом")

        return f"Файл {file_path} успешно проверен"
    except MergeError as e:
        raise
    except Exception as e:
        raise ValueError(f"Неизвестная ошибка: {e}")

