import time
import logging
from typing import Callable, Any, TypeVar, Optional
from functools import wraps

R = TypeVar('R')

def validator(max_attempts: int = 3, delay: float = 1) -> Callable[[Callable[..., R]], Callable[..., Optional[R]]]:
    """
    Декоратор для повторного выполнения функции с экспоненциальной задержкой.

    :param max_attempts: Максимальное количество попыток
    :param delay: Начальная задержка между попытками
    :return: Результат выполнения функции или None, если все попытки неудачны
    """
    if max_attempts < 1:
        raise ValueError("max_attempts must be at least 1")
    if delay < 0:
        raise ValueError("delay must be non-negative")

    def decorator(func: Callable[..., R]) -> Callable[..., Optional[R]]:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Optional[R]:
            attempt = 0
            current_delay = delay
            while attempt < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempt += 1
                    if attempt >= max_attempts:
                        logging.error(f"Max attempts reached for {func.__name__}: {e}")
                        return None
                    time.sleep(current_delay)
                    current_delay *= 2  # Экспоненциальная задержка
        return wrapper
    return decorator

