from __future__ import annotations
from abc import ABC, abstractmethod
from typing import Any, Optional


class Handler(ABC):
    """
    Abstract base class for all handlers in the chain.
    """

    _next_handler: Optional["Handler"] = None

    def set_next(self, handler: "Handler") -> "Handler":
        """
        Set the next handler in the chain and return it so calls can be chained.

        Example:
            h1.set_next(h2).set_next(h3)
        """
        self._next_handler = handler
        return handler

    @abstractmethod
    def handle(self, request: Any) -> Any:
        """
        Process the request or forward it to the next handler.

        Returns a result if the handler can process the request,
        otherwise returns the result of the next handler (or None if the end
        of the chain is reached).
        """
        ...

    def _forward(self, request: Any) -> Any:
        """Helper that forwards the request to the next handler, if any."""
        if self._next_handler:
            return self._next_handler.handle(request)
        return None


# ----------------------------------------------------------------------
# Concrete handlers
# ----------------------------------------------------------------------


class EvenNumberHandler(Handler):
    """Handles even integer numbers."""

    def handle(self, request: Any) -> Any:
        if isinstance(request, int) and request % 2 == 0:
            return f"EvenNumberHandler processed {request}"
        return self._forward(request)


class PositiveNumberHandler(Handler):
    """Handles positive integer numbers (including odd ones)."""

    def handle(self, request: Any) -> Any:
        if isinstance(request, int) and request > 0:
            return f"PositiveNumberHandler processed {request}"
        return self._forward(request)


class DefaultHandler(Handler):
    """Fallback handler – processes everything that reached the end."""

    def handle(self, request: Any) -> Any:
        return f"DefaultHandler could not process {request!r}"


# ----------------------------------------------------------------------
# Example usage
# ----------------------------------------------------------------------


def main() -> None:
    # Build the chain: Even → Positive → Default
    even_handler = EvenNumberHandler()
    positive_handler = PositiveNumberHandler()
    default_handler = DefaultHandler()

    even_handler.set_next(positive_handler).set_next(default_handler)

    # Test data
    test_requests = [4, 7, -3, "hello", 0]

    for req in test_requests:
        result = even_handler.handle(req)
        print(f"Request {req!r}: {result}")


if __name__ == "__main__":
    main()

