class Handler(ABC):
    """
    Abstract base class for all handlers in the chain.
    """

    _next_handler: 'Handler' = None

    def set_next(self, handler: 'Handler') -> 'Handler':
        """
        Set the next handler in the chain and return it so calls can be chained.

        Example:
            h1.set_next(h2).set_next(h3)
        """
        self._next_handler = handler
        return handler

    @abstractmethod
    def handle(self, request: str) -> None:
        """
        Handle the request or pass it to the next handler in the chain.
        """
        if self._next_handler:
            self._next_handler.handle(request)

