class Serializer:
    def __init__(self):
        self.items: list = []

    def push(self, item) -> None:
        """Добавляет элемент в сериализатор."""
        try:
            self.items.append(item)
        except Exception as e:
            print(f"Ошибка при добавлении элемента: {e}")

    def pop(self) -> any:
        """Удаляет и возвращает последний добавленный элемент. Возвращает None, если сериализатор пуст."""
        try:
            if not self.is_empty():
                return self.items.pop()
            return None
        except Exception as e:
            print(f"Ошибка при удалении элемента: {e}")

    def peek(self) -> any:
        """Возвращает последний добавленный элемент без его удаления. Возвращает None, если сериализатор пуст."""
        try:
            if not self.is_empty():
                return self.items[-1]
            return None
        except Exception as e:
            print(f"Ошибка при просмотре элемента: {e}")

    def is_empty(self) -> bool:
        """Проверяет, пуст ли сериализатор."""
        return len(self.items) == 0

def buffer(data, chunk_size):
    """
    Буферизует данные через генератор.

    Пример использования:
    for chunk in buffer(some_data, some_chunk_size):
        print(chunk)
    """
    try:
        buffer = []
        for item in data:
            buffer.append(item)
            if len(buffer) >= chunk_size:
                yield buffer
                buffer = []
        if buffer:  # Выдать оставшуюся часть
            yield buffer
    except Exception as e:
        print(f"Ошибка при буферизации данных: {e}")

