def setup_testing_tools(file_paths: list) -> dict:
    aggregated_results = {'total_tests': 0, 'successful_tests': 0, 'failed_tests': 0, 'errors': []}

    for file_path in file_paths:
        try:
            with open(file_path, 'r') as file:
                data = json.load(file)

            # Проверка наличия ключа 'tests'
            if 'tests' not in data:
                aggregated_results['errors'].append(f"No tests found in {file_path}")
                continue

            for test in data['tests']:
                aggregated_results['total_tests'] += 1
                try:
                    # Проверка наличия метода 'run' перед вызовом
                    if hasattr(test, 'run') and callable(getattr(test, 'run')):
                        result = test.run()
                        if result:
                            aggregated_results['successful_tests'] += 1
                        else:
                            aggregated_results['failed_tests'] += 1
                    else:
                        aggregated_results['errors'].append(f"Test in {file_path} does not have a 'run' method")
                except Exception as e:
                    aggregated_results['errors'].append(f"Error in test execution from {file_path}: {str(e)}")

        except FileNotFoundError:
            aggregated_results['errors'].append(f"File not found: {file_path}")
        except json.JSONDecodeError:
            aggregated_results['errors'].append(f"JSON decode error in {file_path}")

    return aggregated_results

