import hashlib

def resolver(data, hash_type):
    cache = {}

    try:
        # Проверяем наличие результата в кэше
        if data in cache:
            return cache[data]

        # Создание объекта hash на основе типа хеша
        if hash_type == 'md5':
            hash_obj = hashlib.md5()
        elif hash_type == 'sha1':
            hash_obj = hashlib.sha1()
        elif hash_type == 'sha256':
            hash_obj = hashlib.sha256()
        else:
            raise ValueError(f"Неподдерживаемый тип хеша: {hash_type}")

        # Обновление объекта hash данными
        hash_obj.update(data.encode('utf-8'))

        # Получение результата и сохранение в кэше
        result = hash_obj.hexdigest()
        cache[data] = result

        return result

    except Exception as e:
        print(f"Ошибка при вычислении хеша: {e}")

