class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def dfs_logarithmic(root):
    try:
        if not root:
            return []

        stack = [root]
        result = []
        while stack:
            node = stack.pop()
            result.append(node.value)
            # Добавляем правое поддерево первым, чтобы левое обрабатывалось раньше
            if node.right:
                stack.append(node.right)
            if node.left:
                stack.append(node.left)

        return result

    except Exception as e:
        print(f"Произошла ошибка: {e}")
        return []

