import asyncio
from typing import List, Optional, TypeVar, Generic

# Определяем универсальный тип T для поддержки любой типизации (int, str, CustomClass и т.д.)
T = TypeVar('T')

class AsyncObserver(Generic[T]):
    """
    Асинхронный наблюдатель, поддерживающий добавление, удаление и поиск элементов.
    """

    def __init__(self):
        self._items: List[T] = []

    async def add(self, item: T) -> None:
        try:
            if item not in self._items:
                self._items.append(item)
        except Exception as e:
            print(f"Error adding item: {e}")

    async def remove(self, item: T) -> bool:
        try:
            if item in self._items:
                self._items.remove(item)
                return True
            return False
        except Exception as e:
            print(f"Error removing item: {e}")
            return False

    async def find(self, item: T) -> Optional[T]:
        try:
            if item in self._items:
                return item
            return None
        except Exception as e:
            print(f"Error finding item: {e}")
            return None

