from threading import Lock

class ThreadSafeHashMap:
    def __init__(self):
        self._map = {}
        self._lock = Lock()

    def put(self, key: any, value: any) -> None:
        """Добавляет элемент в HashMap."""
        if key is None or value is None:
            raise ValueError("Key and value cannot be None")
        with self._lock:
            self._map[key] = value

    def get(self, key: any) -> any:
        """Извлекает и возвращает значение по ключу из HashMap."""
        if key is None:
            raise ValueError("Key cannot be None")
        with self._lock:
            return self._map.get(key)

    def remove(self, key: any) -> bool:
        """Удаляет элемент из HashMap и возвращает True, если элемент был найден."""
        if key is None:
            raise ValueError("Key cannot be None")
        with self._lock:
            if key in self._map:
                del self._map[key]
                return True
            return False

    def contains_key(self, key: any) -> bool:
        """Проверяет наличие ключа в HashMap."""
        if key is None:
            raise ValueError("Key cannot be None")
        with self._lock:
            return key in self._map

    def size(self) -> int:
        """Возвращает количество элементов в HashMap."""
        with self._lock:
            return len(self._map)

