from threading import Lock
from typing import Any, Hashable, Mapping, Optional

class ThreadSafeHashMap(Mapping[Hashable, Any]):
    def __init__(self):
        self._lock = Lock()
        self._data: dict[Hashable, Any] = {}

    def __getitem__(self, key: Hashable) -> Any:
        with self._lock:
            return self._data[key]

    def __setitem__(self, key: Hashable, value: Any) -> None:
        with self._lock:
            self._data[key] = value

    def __delitem__(self, key: Hashable) -> None:
        with self._lock:
            del self._data[key]

    def __contains__(self, key: Hashable) -> bool:
        with self._lock:
            return key in self._data

    def __len__(self) -> int:
        with self._lock:
            return len(self._data)

    def __iter__(self) -> iter:
        with self._lock:
            return iter(self._data)

    def get(self, key: Hashable, default: Optional[Any] = None) -> Any:
        with self._lock:
            return self._data.get(key, default)

    def put(self, key: Hashable, value: Any) -> None:
        with self._lock:
            self._data[key] = value

    def remove(self, key: Hashable) -> None:
        with self._lock:
            del self._data[key]

    def clear(self) -> None:
        with self._lock:
            self._data.clear()

# Пример использования
if __name__ == "__main__":
    import threading

    def worker(hash_map: ThreadSafeHashMap, key: Hashable, value: Any) -> None:
        hash_map[key] = value
        print(f"Worker {threading.current_thread().name} wrote {key} = {value}")

    hash_map = ThreadSafeHashMap()

    threads = []
    for i in range(10):
        thread = threading.Thread(target=worker, args=(hash_map, i, f"value_{i}"))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    print("Final hash map:")
    for key, value in hash_map.items():
        print(f"{key} = {value}")

