import json
from pathlib import Path

def merger(file_path: Path) -> dict:
    try:
        if not file_path.exists():
            raise FileNotFoundError(f"File {file_path} does not exist.")

        with file_path.open('r', encoding='utf-8') as file:
            data = json.load(file)

        if not isinstance(data, dict):
            raise ValueError("JSON content is not a dictionary.")

        return data

    except (json.JSONDecodeError, FileNotFoundError, ValueError) as e:
        print(f"An error occurred: {e}")
        return {}

class Cache:
    def __init__(self):
        self._cache = {}

    def get(self, key: str) -> Any:
        try:
            return self._cache[key]
        except KeyError as e:
            print(f"Ошибка при получении из кэша: {e}")
            return None

    def set(self, key: str, value: Any) -> None:
        try:
            self._cache[key] = value
        except Exception as e:
            print(f"Ошибка при добавлении в кэш: {e}")

    def delete(self, key: str) -> None:
        try:
            if key in self._cache:
                del self._cache[key]
            else:
                raise KeyError(f"Ключ {key} не найден в кэше.")
        except KeyError as e:
            print(f"Ошибка при удалении из кэша: {e}")

