import pytest

# Предположим, что файл converter.py содержит следующий код:
from typing import Any, Dict

def converter(data: Dict[str, Any]) -> Dict[str, Any]:
    """
    Функция для преобразования данных.

    Параметры:
        data (Dict[str, Any]): Словарь с данными для преобразования.

    Возвращает:
        Dict[str, Any]: Преобразованный словарь данных.
    """
    try:
        # Обработка edge cases
        if not isinstance(data, dict):
            raise ValueError("Input data must be a dictionary")

        # Пример преобразования: приведение всех ключей к нижнему регистру
        return {k.lower(): v for k, v in data.items()}
    except Exception as e:
        print(f"An error occurred: {e}")
        raise

# Тесты для функции converter
def test_converter_normal_case():
    input_data = {"Name": "John", "Age": 30}
    expected_output = {"name": "john", "age": 30}
    assert converter(input_data) == expected_output

def test_converter_empty_dict():
    input_data = {}
    expected_output = {}
    assert converter(input_data) == expected_output

def test_converter_non_dict_input():
    with pytest.raises(ValueError):
        converter([1, 2, 3])

def test_converter_nested_dict():
    input_data = {"Name": "John", "Address": {"Street": "123 Main St"}}
    expected_output = {"name": "john", "address": {"street": "123 main st"}}
    assert converter(input_data) == expected_output

def test_converter_mixed_case_keys():
    input_data = {"FirstName": "John", "LastName": "Doe"}
    expected_output = {"firstname": "john", "lastname": "doe"}
    assert converter(input_data) == expected_output

