import unittest
from resolver import Resolver

class TestResolver(unittest.TestCase):
    def setUp(self) -> None:
        self.resolver = Resolver()

    def test_start_running(self) -> None:
        self.resolver.start()
        with self.assertRaises(RuntimeError):
            self.resolver.start()

    def test_stop_not_running(self) -> None:
        with self.assertRaises(RuntimeError):
            self.resolver.stop()

    def test_status_initial(self) -> None:
        self.assertFalse(self.resolver.status())

    def test_status_after_start(self) -> None:
        self.resolver.start()
        self.assertTrue(self.resolver.status())

    def test_status_after_stop(self) -> None:
        self.resolver.start()
        self.resolver.stop()
        self.assertFalse(self.resolver.status())

if __name__ == '__main__':
    unittest.main()

