from typing import List, Optional

def binary_search(arr: List[int], target: int) -> Optional[int]:
    """
    Функция для выполнения бинарного поиска.

    :param arr: Отсортированный список целых чисел.
    :param target: Искомое число.
    :return: Индекс искомого элемента или None, если элемент не найден.
    """
    if not isinstance(arr, list):
        raise TypeError("Аргумент должен быть списком.")

    if len(arr) == 0:
        return None

    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return None

