import time

def dispatcher(max_retries=3, delay=1):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except (IOError, OSError) as e:
                    print(f"Attempt {attempts + 1} failed due to IO/OSError: {e}")
                    time.sleep(delay)
                    attempts += 1
                except Exception as e:
                    print(f"Attempt {attempts + 1} failed with unexpected error: {e}")
                    break
            raise Exception("Max retries reached")
        return wrapper
    return decorator

