from typing import Optional, AsyncContextManager
import aiofiles

class AsyncFileContextManager(AsyncContextManager):
    def __init__(self, file_path: str, mode: str = 'r', encoding: str = 'utf-8'):
        self.file_path = file_path
        self.mode = mode
        self.encoding = encoding
        self._file: Optional[aiofiles.FileIO] = None

    async def __aenter__(self) -> 'AsyncFileContextManager':
        try:
            if not await asyncio.to_thread(self._check_file_exists):
                raise FileNotFoundError(f"File {self.file_path} does not exist")
            self._file = await aiofiles.open(self.file_path, mode=self.mode, encoding=self.encoding)
            return self
        except Exception as e:
            await self.__aexit__(None, None, e)
            raise

    async def __aexit__(self, exc_type: Optional[type], exc_val: Optional[Exception], exc_tb: Optional[object]) -> bool:
        if self._file:
            try:
                await self._file.close()
            except Exception as e:
                print(f"Error closing file {self.file_path}: {e}")
        return False

    def _check_file_exists(self) -> bool:
        import os
        return os.path.exists(self.file_path)

    async def read(self, n: int = -1) -> str:
        if not self._file:
            raise RuntimeError("File is not opened")
        return await self._file.read(n)

