from typing import List, Optional

class Token:
    """Токен в выражении"""
    __slots__ = ('type', 'value')

    def __init__(self, type: str, value: int):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'


class Parser:
    """Парсер выражений"""
    __slots__ = ('tokens', 'pos', '_memo')

    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self._memo = {}

    def parse(self) -> Optional[int]:
        try:
            return self._parse_expression()
        except IndexError:
            raise ValueError("Unexpected end of input")

    def _parse_expression(self) -> int:
        if self.pos in self._memo:
            return self._memo[self.pos]

        result = self._parse_term()
        while self._peek().type == 'PLUS':
            self._next_token()
            result += self._parse_term()

        self._memo[self.pos] = result
        return result

    def _parse_term(self) -> int:
        result = self._parse_factor()
        while self._peek().type == 'MUL':
            self._next_token()
            result *= self._parse_factor()

        return result

    def _parse_factor(self) -> int:
        token = self._next_token()
        if token.type == 'NUMBER':
            return token.value
        elif token.type == 'LPAREN':
            result = self._parse_expression()
            if self._next_token().type != 'RPAREN':
                raise ValueError("Mismatched parentheses")
            return result
        else:
            raise ValueError(f"Unexpected token: {token}")

    def _peek(self) -> Token:
        try:
            return self.tokens[self.pos]
        except IndexError:
            return Token('EOF', 0)

    def _next_token(self) -> Token:
        if self.pos >= len(self.tokens):
            raise IndexError("No more tokens")
        token = self.tokens[self.pos]
        self.pos += 1
        return token

