def bfs(graph: dict, start_vertex: str) -> list:
    try:
        visited = set()
        queue = deque([start_vertex])
        result = []

        while queue:
            vertex = queue.popleft()
            if vertex not in visited:
                visited.add(vertex)
                result.append(vertex)
                for neighbor in graph.get(vertex, []):
