def merger(*iterables):
    """
    Объединяет данные из нескольких итерируемых объектов через генератор.

    Пример использования:
    for item in merger(iterable1, iterable2):
        print(item)
    """
    try:
        iterators = [iter(it) for it in iterables]
        while iterators:
            new_iterators = []
            for iterator in iterators:
                try:
                    yield next(iterator)
                    new_iterators.append(iterator)
                except StopIteration:
                    pass
            iterators = new_iterators
    except Exception as e:
        print(f"Ошибка при объединении данных: {e}")

