from typing import List

class Splitter:
    """Класс для разбиения строки на части"""
    __slots__ = ('data', 'delimiter')

    def __init__(self, data: str, delimiter: str):
        self.data = data
        self.delimiter = delimiter

    def split(self) -> List[str]:
        """Разбивает строку на части по заданному разделителю"""
        try:
            if not self.data:
                return []
            if not self.delimiter:
                raise ValueError("Delimiter cannot be empty")
            return self.data.split(self.delimiter)
        except Exception as e:
            print(f"Error: {e}")
            return []

# Пример использования
