class Serializer:
    def serialize(self, obj) -> str:
        """Сериализует объект в строку."""
        if obj is None:
            raise ValueError("Object to serialize cannot be None.")

        try:
            yield self._serialize(obj)
        except Exception as e:
            raise RuntimeError(f"Serialization failed: {e}")

    def _serialize(self, obj) -> str:
        """Внутренний метод для сериализации объекта."""
        if isinstance(obj, dict):
            for key, value in obj.items():
                yield f'"{key}": {self._serialize(value)},'
        elif isinstance(obj, list):
            for item in obj:
                yield self._serialize(item) + ','
        elif isinstance(obj, str):
            yield f'"{obj}"'
        elif isinstance(obj, (int, float)):
            yield str(obj)
        else:
            raise TypeError(f"Unsupported type: {type(obj)}")

