import hashlib

def buffer(data: list) -> list:
    """
    Функция для фильтрации списка данных через hashlib.

    :param data: Список строковых данных для фильтрации.
    :return: Список хешей от каждой строки в списке.
    """
    if not isinstance(data, list):
        raise TypeError("Первый аргумент должен быть списком.")

    try:
        return [hashlib.sha256(item.encode()).hexdigest() for item in data]
    except Exception as e:
        raise ValueError(f"Ошибка при обработке данных: {e}")

