import hashlib

def buffer(data: list[str]) -> list[str]:
    """Фильтрует список строк через hashlib."""
    if not data:
        return []

    try:
        filtered_data = []
        for item in data:
            if isinstance(item, str):
                hash_object = hashlib.sha256(item.encode())
                filtered_data.append(hash_object.hexdigest())
            else:
                raise ValueError("All items must be strings.")

        return filtered_data
    except Exception as e:
        raise RuntimeError(f"Filtering failed: {e}")

