class Validator:
    def validate_int(self, value: str) -> int:
        try:
            if not isinstance(value, int):
                raise InvalidTypeError("Значение должно быть целым числом")
            return value
        except Exception as e:
            raise ValidatorError(f"Ошибка валидации: {e}")

    def validate_range(self, value: int, min_value: int, max_value: int) -> int:
        try:
            if not (min_value <= value <= max_value):
                raise ValueOutOfRangeError("Значение вне допустимого диапазона")
            return value
        except Exception as e:
            raise ValidatorError(f"Ошибка валидации: {e}")

