import os

class Cache:
    def __init__(self, cache_file: str):
        self._cache = {}
        self._connected = False
        self._cache_file = cache_file

    def connect(self) -> None:
        try:
            if not self._connected:
                if os.path.exists(self._cache_file):
                    with open(self._cache_file, 'r', encoding='utf-8') as file:
                        self._cache = eval(file.read())
                self._connected = True
                print("Connected to cache.")
            else:
                print("Already connected.")
        except Exception as e:
            print(f"Connection error: {e}")

    def send(self, key: str, value: any) -> None:
        try:
            if self._connected:
                self._cache[key] = value
                print(f"Data sent to cache: {key}={value}")
            else:
                print("Not connected to cache.")
        except Exception as e:
            print(f"Send error: {e}")

    def close(self) -> None:
        try:
            if self._connected:
                with open(self._cache_file, 'w', encoding='utf-8') as file:
                    file.write(str(self._cache))
                self._connected = False
                print("Cache connection closed.")
            else:
                print("Already disconnected.")
        except Exception as e:
            print(f"Close error: {e}")

from enum import Enum

class SerializerStatus(Enum):
    """Статус сериализатора"""
    STOPPED = 1
    RUNNING = 2

class Serializer:
    """Класс сериализатора"""
    def __init__(self) -> None:
        """Инициализация сериализатора"""
        self._status: SerializerStatus = SerializerStatus.STOPPED

    def start(self) -> None:
        """Запуск сериализатора"""
        try:
            if self._status == SerializerStatus.RUNNING:
                raise RuntimeError("Сериализатор уже запущен")
            self._status = SerializerStatus.RUNNING
        except Exception as e:
            print(f"Ошибка при запуске: {e}")

    def stop(self) -> None:
        """Остановка сериализатора"""
        try:
            if self._status == SerializerStatus.STOPPED:
                raise RuntimeError("Сериализатор уже остановлен")
            self._status = SerializerStatus.STOPPED
        except Exception as e:
            print(f"Ошибка при остановке: {e}")

    def status(self) -> str:
        """Статус сериализатора"""
        try:
            return self._status.name
        except Exception as e:
            print(f"Ошибка при получении статуса: {e}")
            return "UNKNOWN"

import logging

class Cache:
    def __init__(self):
        self._cache = {}
        self._connected = False
        logging.basicConfig(level=logging.INFO)

    def connect(self) -> None:
        try:
            if not self._connected:
                self._connected = True
                logging.info("Connected to cache.")
            else:
                logging.warning("Already connected.")
        except Exception as e:
            logging.error(f"Connection error: {e}")

    def set(self, key: str, value) -> None:
        try:
            if not self._connected:
                raise ConnectionError("Not connected to the cache.")
            self._cache[key] = value
            logging.info(f"Set key '{key}' with value '{value}'.")
        except Exception as e:
            logging.error(f"Failed to set key: {e}")

    def get(self, key: str):
        try:
            if not self._connected:
                raise ConnectionError("Not connected to the cache.")
            return self._cache.get(key)
        except Exception as e:
            logging.error(f"Failed to get key: {e}")

class MemoryEfficientMerger:
    __slots__ = ('data1', 'data2', 'index1', 'index2')

    def __init__(self, data1: list, data2: list):
        self.data1 = sorted(data1)
        self.data2 = sorted(data2)
        self.index1 = 0
        self.index2 = 0

    def __iter__(self) -> 'MemoryEfficientMerger':
        return self

    def __next__(self) -> any:
        try:
            if self.index1 < len(self.data1) and self.index2 < len(self.data2):
                if self.data1[self.index1] <= self.data2[self.index2]:
                    result = self.data1[self.index1]
                    self.index1 += 1
                else:
                    result = self.data2[self.index2]
                    self.index2 += 1
            elif self.index1 < len(self.data1):
                result = self.data1[self.index1]
                self.index1 += 1
            elif self.index2 < len(self.data2):
                result = self.data2[self.index2]
                self.index2 += 1
            else:
                raise StopIteration
            return result
        except Exception as e:
            print(f"An error occurred: {e}")
            raise StopIteration

