from pathlib import Path

class IteratorError(Exception):
    """Базовое исключение для ошибок в функции iterator."""
    pass

class NonExistentPathError(IteratorError):
    """Исключение, возникающее при попытке итерировать несуществующий путь."""
    pass

class NotADirectoryError(IteratorError):
    """Исключение, возникающее при попытке итерировать путь, который не является директорией."""
    pass

def iterator(path: str) -> Path:
    try:
        dir_path = Path(path)

        if not dir_path.exists():
            raise NonExistentPathError("Указанный путь не существует.")

        if not dir_path.is_dir():
            raise NotADirectoryError("Указанный путь не является директорией.")

        for item in dir_path.iterdir():
            yield item

    except Exception as e:
        raise IteratorError(f"Ошибка при итерировании: {e}")

