        return list(itertools.filterfalse(lambda x: not predicate(x), data))
    except Exception as e:
        print(f"Error in parser: {e}")
        return []

def test_parser():
    try:
        # Тест 1: Простой список чисел
        assert parser([1, 2, 3, 4, 5], lambda x: x % 2 == 0) == [2, 4]

        # Тест 2: Список со строками
        assert parser(["apple", "banana", "cherry"], lambda x: len(x) > 5) == ["banana", "cherry"]

        # Тест 3: Список с None значениями
        assert parser([None, 1, 2, None, 3], lambda x: x is not None) == [1, 2, 3]

        # Тест 4: Пустой список
        assert parser([], lambda x: x > 0) == []

        # Тест 5: Список с отрицательными числами
        assert parser([-1, -2, -3, 0, 1], lambda x: x < 0) == [-1, -2, -3]

        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")

if __name__ == "__main__":
    test_parser()

def parser(data):
    """
    Парсер данных через генератор.

    Пример использования:
    for item in parser(some_data):
        print(item)
    """
    try:
        buffer = ""
        for char in data:
            if char == " ":  # Предположим, что разделитель - пробел
                yield buffer
                buffer = ""
            else:
                buffer += char
        yield buffer  # Выдать оставшуюся часть
    except Exception as e:
        print(f"Ошибка при парсинге данных: {e}")

