class Dispatcher:
    __slots__ = ('routes',)

    def __init__(self):
        self.routes: dict[str, callable] = {}

    def register(self, route: str) -> None:
        if not isinstance(route, str):
            raise TypeError("Route must be a string")
        self.routes[route] = self.handle_request

    def handle_request(self, request: str) -> str:
        if not isinstance(request, str):
            raise TypeError("Request must be a string")
        handler = self.routes.get(request)
        if handler is None:
            return "404 Not Found"
        return handler()

    def dispatch(self, request: str) -> str:
        try:
            return self.handle_request(request)
        except Exception as e:
            return f"500 Internal Server Error: {str(e)}"

