from enum import Enum

class ParserStatus(Enum):
    """Статус парсера"""
    STOPPED = 1
    RUNNING = 2

class Parser:
    """Класс парсера"""
    def __init__(self) -> None:
        """Инициализация парсера"""
        self._status: ParserStatus = ParserStatus.STOPPED

    def start(self) -> None:
        """Запуск парсера"""
        if self._status == ParserStatus.RUNNING:
            raise RuntimeError("Парсер уже запущен")
        self._status = ParserStatus.RUNNING
        print("Парсер запущен")

    def stop(self) -> None:
        """Остановка парсера"""
        if self._status == ParserStatus.STOPPED:
            raise RuntimeError("Парсер уже остановлен")
        self._status = ParserStatus.STOPPED
        print("Парсер остановлен")

    def status(self) -> str:
        """Статус парсера"""
        return self._status.name

