import json
from requests import RequestException, Timeout, NetworkError

def serializer(func: callable) -> callable:
    """Декоратор для сериализации ответа в JSON с обработкой ошибок."""

    def wrapper(*args, **kwargs) -> str:
        try:
            response = func(*args, **kwargs)
            if not response.ok:
                raise ValueError(f"Unexpected status code: {response.status_code}")
            data = response.json()
            if data is None or not data:
                raise ValueError("Received empty or invalid JSON data")
            return json.dumps(data)
        except (NetworkError, Timeout) as e:
            raise ConnectionError(f"Connection error occurred: {e}") from e
        except RequestException as e:
            raise ValueError(f"Request failed: {e}") from e
        except Exception as e:
            raise RuntimeError(f"An unexpected error occurred: {e}") from e

    return wrapper

class Dispatcher:
    __slots__ = ('routes',)

    def __init__(self):
        self.routes: dict[str, callable] = {}

    def register(self, route: str, handler: callable) -> None:
        if not isinstance(route, str):
            raise TypeError("Route must be a string")
        if not callable(handler):
            raise TypeError("Handler must be a callable function")
        self.routes[route] = handler

    def handle_request(self, request: str) -> any:
        if not isinstance(request, str):
            raise TypeError("Request must be a string")
        handler = self.routes.get(request)
        if handler is None:
            raise ValueError(f"No handler registered for route: {request}")
        return handler()

